import os, sys, marshal
from collections import Counter

def count_range(buf):
    counts = Counter()
    update = counts.update
    CHUNK = 524288
    n = len(buf)
    pos = 0
    ws = b' \t\n\r\x0b\x0c'
    while pos < n:
        nxt = min(pos + CHUNK, n)
        if nxt < n:
            while nxt < n and buf[nxt] not in ws:
                nxt += 1
        update(buf[pos:nxt].split())
        pos = nxt
    res = {}
    for w, c in counts.items():
        lw = w.lower()
        res[lw] = res.get(lw, 0) + c
    return res

def main():
    try:
        size = os.fstat(0).st_size
    except Exception:
        size = 0

    if size > 500_000:
        nworkers = 8
        step = size // nworkers
        bounds = [0]
        ws = b' \t\n\r\x0b\x0c'
        for i in range(1, nworkers):
            p = i * step
            b = os.pread(0, 256, p)
            j = 0
            while j < len(b) and b[j] not in ws:
                j += 1
            bounds.append(p + j)
        bounds.append(size)

        pipes = []
        pids = []
        for i in range(1, nworkers):
            r, w = os.pipe()
            pid = os.fork()
            if pid == 0:
                os.close(r)
                s, e = bounds[i], bounds[i+1]
                c = count_range(os.pread(0, e - s, s))
                os.write(w, marshal.dumps(c))
                os.close(w)
                os._exit(0)
            else:
                os.close(w)
                pipes.append(r)
                pids.append(pid)

        total = count_range(os.pread(0, bounds[1], 0))
        for r in pipes:
            chunks = []
            while True:
                b = os.read(r, 65536)
                if not b:
                    break
                chunks.append(b)
            os.close(r)
            d = marshal.loads(b"".join(chunks))
            for k, v in d.items():
                total[k] = total.get(k, 0) + v
        for pid in pids:
            os.waitpid(pid, 0)
    else:
        total = {}
        for w, c in Counter(sys.stdin.buffer.read().split()).items():
            lw = w.lower()
            total[lw] = total.get(lw, 0) + c

    top10 = sorted(total.items(), key=lambda x: (-x[1], x[0]))[:10]
    for w, c in top10:
        print(f"{w.decode('utf-8')} {c}")

if __name__ == "__main__":
    main()

